import express from 'express';
import cors from 'cors';
async function cab(origem) {
  if (origem === undefined) delete process.env.CORS_ORIGIN; else process.env.CORS_ORIGIN = origem;
  const app = express();
  app.use(cors({ origin: process.env.CORS_ORIGIN || '*' }));
  app.get('/x', (req, res) => res.end('ok'));
  const srv = app.listen(0, '127.0.0.1');
  await new Promise((r) => srv.once('listening', r));
  const r = await fetch('http://127.0.0.1:' + srv.address().port + '/x', { headers: { Origin: 'https://meu-site.netlify.app' } });
  srv.close();
  return r.headers.get('access-control-allow-origin');
}
const a = await cab(undefined);
const b = await cab('https://meu-site.netlify.app');
console.log('(1) ' + a + ' e (2) ' + b);
process.exit(0);

import express from 'express';
import path from 'node:path';
process.env.NODE_ENV = 'test';
const dist = path.join(DIR, 'dist');
const app = express();
app.get('/reescreve/{*splat}', (req, res) => res.sendFile(path.join(dist, 'index.html')));
app.get('/redireciona/{*splat}', (req, res) => res.redirect(301, '/index.html'));
const srv = app.listen(0, '127.0.0.1');
await new Promise((r) => srv.once('listening', r));
const url = 'http://127.0.0.1:' + srv.address().port;
const pegar = async (caminho, opcoes) => { const r = await fetch(url + caminho, opcoes); return { status: r.status, texto: await r.text(), loc: r.headers.get('location') }; };
const a = await pegar('/reescreve/lugares/1', { redirect: 'manual' });
const b = await pegar('/redireciona/lugares/1', { redirect: 'manual' });
const fmt = (r) => (r.status === 200 ? '200 sem redirecionar' : r.status + ' para ' + r.loc);
console.log(fmt(a) + ' / ' + fmt(b));
srv.close();
process.exit(0);

